package br.com.mecaniQA.api.Repository;
import br.com.mecaniQA.api.model.*; import br.com.mecaniQA.api.Mappers.PecasResultSetMapper; import br.com.mecaniQA.api.Enums.*; import java.sql.*; import java.util.*; import java.time.*;
public class PecasRepository extends JdbcSupport implements Repository<Pecas,Long>{private static final PecasRepository INSTANCE=new PecasRepository();public static PecasRepository getInstance(){return INSTANCE;}public Pecas cadastrar(Pecas x){return save(x);}public List<Pecas>listarTodas(){return findAll();}public Pecas buscarPorCodigo(Long id){return findById(id).orElse(null);}public Pecas atualizarPeca(Long id,Pecas x){x.setCodigoUnico(id);return update(x);}public Pecas deletarPeca(Long id){Pecas x=buscarPorCodigo(id);if(x!=null)deleteById(id);return x;}
 public Pecas save(Pecas x){long id=insert("INSERT INTO pecas(nome,fornecedor_marca,quantidade_estoque,codigo_de_barras,preco_custo,preco_venda,tamanho,cor,categoria_peca) VALUES(?,?,?,?,?,?,?,?,?)",x.getNome(),x.getFornecedorMarca(),x.getQuantidadeEstoque(),x.getCodigoDeBarras(),x.getPrecoCusto(),x.getPrecoVenda(),x.getTamanho(),x.getCor(),x.getCategoriaPeca()==null?null:x.getCategoriaPeca().name());x.setCodigoUnico(id);return x;}public Optional<Pecas>findById(Long id){return query("SELECT * FROM pecas WHERE codigo_unico=?",new PecasResultSetMapper()::map,id).stream().findFirst();}public List<Pecas>findAll(){return query("SELECT * FROM pecas ORDER BY codigo_unico",new PecasResultSetMapper()::map);}public Pecas update(Pecas x){int n=execute("UPDATE pecas SET nome=?,fornecedor_marca=?,quantidade_estoque=?,codigo_de_barras=?,preco_custo=?,preco_venda=?,tamanho=?,cor=?,categoria_peca=?,data_atualizacao=CURRENT_TIMESTAMP WHERE codigo_unico=?",x.getNome(),x.getFornecedorMarca(),x.getQuantidadeEstoque(),x.getCodigoDeBarras(),x.getPrecoCusto(),x.getPrecoVenda(),x.getTamanho(),x.getCor(),x.getCategoriaPeca()==null?null:x.getCategoriaPeca().name(),x.getCodigoUnico());return n==0?null:x;}public void deleteById(Long id){execute("DELETE FROM pecas WHERE codigo_unico=?",id);}public boolean existsById(Long id){return !query("SELECT codigo_unico FROM pecas WHERE codigo_unico=?",r->r.getLong(1),id).isEmpty();}private Pecas map(ResultSet r)throws SQLException{Pecas x=new Pecas(r.getString("nome"),r.getString("fornecedor_marca"),r.getInt("quantidade_estoque"),r.getString("codigo_de_barras"),r.getDouble("preco_custo"),r.getDouble("preco_venda"),r.getString("categoria_peca")==null?null:CategoriaPeca.valueOf(r.getString("categoria_peca")));setId(x,"codigoUnico",r.getLong("codigo_unico"));Object tamanho=r.getObject("tamanho");x.setTamanho(tamanho==null?null:((Number)tamanho).doubleValue());x.setCor(r.getString("cor"));x.setDataAtualizacao(time(r,"data_atualizacao"));return x;}}
